    "ward.growth-source-cdc": "ఆధారం: CDC. 2000 CDC గ్రోత్ చార్ట్‌లు (National Center for Health Statistics) పబ్లిక్ డొమైన్‌లో ఉన్నాయి మరియు CDC వెబ్‌సైట్‌లో ఉచితంగా లభిస్తాయి. ఇక్కడ వీటి వినియోగం CDC, HHS లేదా United States Government ఆమోదాన్ని సూచించదు. ఈ బిల్డ్‌లో క్లినికల్‌గా ధృవీకరించబడలేదు.",
