    "ward.gst-doc-no-number": "(ఇంకా నంబర్ లేదు)",
    "ward.gst-doc-totals": "పన్ను వర్తించేది {taxable} &middot; GST {tax} &middot; మొత్తం {total}",
    "ward.gst-pkg-room-carved": "ఈ ప్యాకేజీలో రోజుకి రూ. 5,000 కంటే ఎక్కువ ఉన్న {days} రూమ్ రోజు(లు) ఉన్నాయి. ప్యాకేజీలోని రూ. {taxable} రూమ్ ఛార్జీలుగా చూపించబడి, 5% వద్ద పన్ను విధించబడుతుంది. ప్యాకేజీలోని మిగిలిన భాగానికి మినహాయింపు ఉంది. విలువ లెక్కించే పద్ధతి: {methodName}.",
    "ward.gst-pkg-room-capped": "ఈ స్టే కోసం రూమ్ టారిఫ్ ప్యాకేజీ ధర కంటే ఎక్కువగా ఉంది. మొత్తం ప్యాకేజీ ధర GST కోసం రూమ్ ఛార్జీలుగా పరిగణించబడింది. జారీ చేయడానికి ముందు ప్యాకేజీ మరియు రూమ్ కేటగిరీని సరిచూసుకోండి.",
    "ward.gst-pkg-room-fallback": "GST సెట్టింగ్‌లలో ఎంచుకున్న వ్యాల్యుయేషన్ ఈ ప్యాకేజీ కోసం ఉపయోగించలేకపోయాము, కాబట్టి పబ్లిష్ చేసిన రూమ్ టారిఫ్ ఉపయోగించబడింది.",
    "ward.gst-pkg-unrecoverable": "ఈ ప్యాకేజీలోని రూమ్ చార్జీలపై Rs {tax} GST హాస్పిటల్ చెల్లించాల్సి ఉంటుంది, ఎందుకంటే పేయర్ ప్యాకేజీ రేటులో GST అదనంగా చేర్చడానికి అనుమతి లేదు.",
    "ward.gst-pkg-tds": "ఈ scheme notified GST TDS deductor గా గుర్తించబడింది: ఇది పన్ను విధించదగిన room charges పై GST TDS ను మినహాయించవచ్చు (Section 51). దీని 10 శాతం claim deduction అనేది income tax TDS మాత్రమే, GST కాదు.",
    "ward.gst-exempt-footnote": "క్లినికల్ ఎస్టాబ్లిష్‌మెంట్ ద్వారా అందే హెల్త్‌కేర్ సర్వీసులకు GST నుండి మినహాయింపు ఉంది (నోటిఫికేషన్ 12/2017-సెంట్రల్ టాక్స్ (రేట్), ఎంట్రీ 74). Admitted పేషెంట్‌కు అందించే మందులు, ఇంప్లాంట్లు, కన్స్యూమబుల్స్ మరియు ఆహారం కూడా ఆ సర్వీసులో భాగమే.",
    "ward.e-invoicing-no-turnover": "E-invoicing ప్రారంభించబడలేదు: మినహాయింపు ఉన్న సప్లైలతో కలిపి ఆసుపత్రి మొత్తం టర్నోవర్ Admin, Price list, GST settings లలో నమోదు చేయబడలేదు. ఈ బిల్లులో ఉన్నదేదీ రిపోర్ట్ చేయబడదు.",
    "ward.e-invoice-exempt-only": "మినహాయింపు ఉన్న సప్లైలు e-invoicing కోసం రిపోర్ట్ చేయబడవు. ఈ Bill of Supply కి IRN లేదు.",
    "ward.e-invoice-mixed-b2b": "ఈ బిల్లులో రిజిస్టర్డ్ పేయర్ కోసం పన్ను వర్తించే మరియు మినహాయింపు ఉన్న ఛార్జీలు ఉన్నాయి. ఇది Tax Invoice గా (e-invoicing కోసం రిపోర్ట్ చేయబడుతుంది) మరియు వేరే Bill of Supply గా జారీ చేయబడుతుంది.",
    "ward.gst-note-late": "సెక్షన్ 34 సమయ పరిమితి దాటిపోయింది: ఈ నోట్ GST లేకుండా జారీ చేయబడింది.",
    "ward.gst-note-refunded": "ఈ నోట్{ref} ద్వారా పేషెంట్‌కు GST రిఫండ్ చేయబడింది.",
    "ward.gst-note-itc": "బయ్యర్ ద్వారా ఇన్‌పుట్ టాక్స్ క్రెడిట్ రివర్సల్ ధృవీకరించబడింది: {ref}.",
    "ward.gst-note-financial": "ఈ నోట్‌పై GST లేదు: ఇది ఫైనాన్షియల్ నోట్, e-invoicing కోసం రిపోర్ట్ చేయబడదు.",
    "ward.gst-room-tariff-missing": "ఈ ప్యాకేజీ {roomCategoryName} లోని రూమ్ డేస్‌ను కవర్ చేస్తుంది, కానీ దీనికి Price list లో ప్రతి రోజుకి రూమ్ టారిఫ్ లేదు. GST ని లెక్కించలేము. ఈ బిల్లును జారీ చేసే ముందు టారిఫ్‌ను జోడించండి.",
    "ward.gst-rate-missing": "ఈ ఐటెమ్‌లు టాక్సబుల్ మరియు Price list లో GST రేటు లేదు, కాబట్టి ఏ బిల్లు సృష్టించబడలేదు: {codes}. అడ్మినిస్ట్రేటర్ ప్రతి రేటును సెట్ చేయాలి; ఏదీ ఊహించబడదు.",
    "ward.gst-note-ask-title": "ఈ క్రెడిట్ నోట్‌పై GST",
    "ward.gst-note-ask-registered": "ఈ క్రెడిట్ నోట్‌పై GST, {payerName} సంబంధిత ఇన్‌పుట్ టాక్స్ క్రెడిట్‌ను రివర్స్ చేసిన తర్వాత మాత్రమే ఆసుపత్రి పన్నును తగ్గిస్తుంది. వారి ధృవీకరణను రికార్డ్ చేయండి.",
    "ward.gst-note-ask-patient": "ఈ క్రెడిట్ నోట్‌పై ఉన్న GST, పేషెంట్‌కు రిఫండ్ చేసినట్లయితే మాత్రమే ఆసుపత్రి పన్నును తగ్గిస్తుంది. ఈ నోట్‌తో Rs {gst} GST ని రిఫండ్ చేయండి, లేదా GST లేకుండా జారీ చేయండి.",
