    "ward.gst-note-opt-refund": "GST తో: ఈ నోట్‌తో పేషెంట్‌కు GST రిఫండ్ చేయబడింది",
    "ward.gst-note-opt-without": "GST లేకుండా",
    "ward.gst-note-ask-ref": "కొనుగోలుదారు యొక్క నిర్ధారణ (లేఖ లేదా రిఫరెన్స్)",
