    "site.admin.seed.intro": "WardSynQ తో రవాణా చేయబడిన క్లినికల్ కంటెంట్. {signatory} దాని ఖచ్చితమైన ప్రస్తుత కంటెంట్‌ను ఆమోదించే వరకు ప్రతి ఐటెమ్ అప్రూవ్ కాలేదు. సంతకం చేయడం అనేది ఆమోదాన్ని రికార్డ్ చేస్తుంది; ఇది ఏ సురక్షిత తనిఖీ ప్రవర్తనను మార్చదు.",
