    "site.admin.hospital.noteWriters.title": "క్లినికల్ నోట్ ఎవరు రాయవచ్చు",
    "site.admin.hospital.noteWriters.intro": "డాక్టర్లు మరియు admins ఎల్లప్పుడూ ఒక నోట్ రాయవచ్చు. పేషెంట్ timeline పై డాక్యుమెంట్ చేయడానికి మీ ఆసుపత్రి నమ్మే ఇతర హోదాను ఎంచుకోండి (Tick చేయండి). ఇది వారు నోట్ రాయడానికి మాత్రమే అనుమతిస్తుంది, మరేదీ కాదు: ఇది వారిని మందులు రాయడానికి, order చేయడానికి లేదా దేనినీ మార్చడానికి అనుమతించదు.",
