    "site.admin.hospital.token.intro": "ప్రతి డిపార్ట్‌మెంట్ విడివిడిగా సంఖ్యలను ఇచ్చేటప్పుడు మాత్రమే ప్రిఫిక్స్‌లు ఉపయోగించబడతాయి, అప్పుడు ప్రతి డిపార్ట్‌మెంట్‌కు స్వంత ప్రిఫిక్స్ అవసరం: ప్రిఫిక్స్ లేని డిపార్ట్‌మెంట్‌లో డెస్క్ టోకెన్ ఇవ్వలేదు. ప్రిఫిక్స్ ఖాళీగా ఉంటే, ఆ కోడ్ ఒకటి నుండి మూడు అక్షరాలు లేదా అంకెలు ఉన్నప్పుడు బూడిద రంగులో చూపిన డిపార్ట్‌మెంట్ కోడ్ ఉపయోగించబడుతుంది. ప్రతి రోజు నంబర్లు మళ్ళీ 1 వద్ద ప్రారంభమవుతాయి మరియు పేషెంట్‌ను మరొక డిపార్ట్‌మెంట్‌లోని గదికి మార్చినప్పుడు కూడా ఇప్పటికే ఇచ్చిన టోకెన్ ఎప్పుడూ మారదు.",
