    "site.admin.security.restoreNote": "డేటాబేస్ కావాలనే పునరుద్ధరించబడితే (ఉదాహరణకు పాయింట్ ఇన్ టైమ్ రీస్టోర్), ఈ నివేదిక నిరీక్షించబడేది మరియు అంగీకరించే వరకు ఉంటుంది. సరైన రీస్టోర్‌ను ఈ ఆసుపత్రి యజమాని మాత్రమే కారణం మరియు ఇన్సిడెంట్ రెఫరెన్స్‌తో అంగీకరించగలరు. ఎవరూ వివరించలేని తేడాను అంగీకరించవద్దు: ముందుగా ఇన్ఫర్మేషన్ గవర్నెన్స్ లీడ్‌ను అడగండి.",
