    "site.admin.export.title": "డేటా ఎగుమతి (FHIR)",
    "site.admin.export.intro": "బ్యాక్‌గ్రౌండ్‌లో ప్రతి రిసోర్స్ రకానికి ఒక ఫైల్ చొప్పున, ఈ ఆసుపత్రి రికార్డును FHIR R4 NDJSONగా ఎగుమతి చేస్తుంది. ఒకేసారి ఒక ఎగుమతి మాత్రమే నడుస్తుంది. ఫైల్‌లు ఇక్కడ లేదా FHIR బల్క్ డేటా API ($export-status) ద్వారా, ఈ ఆసుపత్రి ప్రామాణీకరణతో డౌన్‌లోడ్ చేయబడతాయి; ప్రతి డౌన్‌లోడ్ ఆడిట్ ట్రయిల్‌లో నమోదు చేయబడుతుంది, మరియు 24 గంటల తర్వాత ఫైల్‌లు తొలగించబడతాయి.",
