    "site.admin.webhooks.status.autoDisabled": "వరుస వైఫల్యాల తర్వాత ఆపివేయబడింది",
    "site.admin.webhooks.title": "వెబ్‌హుక్స్",
    "site.admin.webhooks.intro1": "Webhook అనేది ఇక్కడ ఏదో జరిగిందని మరొక సిస్టమ్‌కు తెలియజేస్తుంది. ఇది ఈవెంట్ రకం మరియు పారదర్శకం కాని idని మాత్రమే కలిగి ఉంటుంది: పేరు, సంఖ్య, పరీక్ష లేదా విలువ ఎప్పుడూ ఉండవు.",
    "site.admin.webhooks.intro2": "స్వీకరించే సిస్టమ్ వివరాలను WardSynQ FHIR API ద్వారా దాని స్వంత SMART యాక్సెస్‌తో చదువుతుంది, ఇక్కడ ఈ ఆసుపత్రి అనుమతులు మరియు ఆడిట్ ట్రయల్ వర్తిస్తాయి.",
    "site.admin.webhooks.intro3": "ప్రతి కాల్ సంతకం చేయబడుతుంది: X-WardSynQ-Signature అనేది X-WardSynQ-Timestamp, ఒక డాట్ మరియు బాడీ యొక్క HMAC-SHA256, ఎండ్‌పాయింట్ రహస్యంతో ఉంటుంది.",
    "site.admin.webhooks.loading": "Webhooks లోడ్ అవుతున్నాయి...",
