    "site.admin.webhooks.copyNow": "దాన్ని ఇప్పుడే కాపీ చేయండి. అది మళ్లీ చూపబడదు. మునుపటి సీక్రెట్ 24 గంటల పాటు పనిచేస్తూనే ఉంటుంది కాబట్టి స్వీకరించే సిస్టమ్‌ను అప్‌డేట్ చేయవచ్చు (లేదు).",
