    "site.admin.growth.title": "గ్రోత్ చార్ట్‌లు",
    "site.admin.growth.intro": "పిల్లల గ్రోత్ చార్ట్‌లు CDC 2000 గ్రోత్ రిఫరెన్స్‌ను ఉపయోగిస్తాయి, ఇది పబ్లిక్ డొమైన్‌లో ఉంది. WHO లేదా IAP వంటి ఇతర గ్రోత్ టేబుల్‌లను ఉపయోగించడానికి లైసెన్స్ ఉన్న ఆసుపత్రి వారి L, M మరియు S విలువలను ఇక్కడ లోడ్ చేయవచ్చు, మరియు చార్ట్‌లు వాటిని ఉపయోగిస్తాయి.",
    "site.admin.growth.listFailed": "గ్రోత్ టేబుల్‌లను చదవడం కుదరలేదు. దీనిని CDC రిఫరెన్స్ ఉపయోగంలో ఉన్నట్లు భావించవద్దు.",
