    "site.admin.growth.file": "CSV లేదా ట్యాబ్-సెపరేటెడ్ ఫైల్",
    "site.admin.growth.columns": "మొదటి వరుస indicator, sex, x, l, m మరియు s కాలమ్ పేర్లను కలిగి ఉంటుంది. indicator అనేది wfa (వయస్సుకు తగ్గ బరువు), lhfa (వయస్సుకు తగ్గ పొడవు లేదా ఎత్తు), wfl (పొడవుకు తగ్గ బరువు, 2 సంవత్సరాల లోపు), wfh (ఎత్తుకు తగ్గ బరువు, 2 సంవత్సరాల నుండి), bmi లేదా hcfa (తల చుట్టుకొలత); sex అనేది 1 లేదా 2; x అనేది నెలల్లో వయస్సు, లేదా wfl మరియు wfh కొరకు cm లో పొడవు లేదా ఎత్తు. ఒక్క చెడు వరుస ఉన్నా ఏదీ లోడ్ కాదు.",
