    "site.admin.hospital.bloodCentre.loadFailed": "బ్లడ్ సెంటర్ సెట్టింగ్‌లు లోడ్ కాలేదు. దీనిని రూల్స్ విలువల అమలులో ఉన్నట్లుగా పరిగణించవద్దు.",
    "site.admin.hospital.bloodCentre.intro": "Drugs and Cosmetics Rules 1945 లైసెన్స్ పొందిన బ్లడ్ సెంటర్ కోసం వీటిని నిర్దేశిస్తాయి. ఈ ఆసుపత్రి వీటిని మరింత కఠినతరం మాత్రమే చేయవచ్చు: NAT ని తప్పనిసరి చేయడం, షెల్ఫ్ లైఫ్‌ను తగ్గించడం, శాంపిల్స్ లేదా రికార్డులను ఎక్కువ కాలం ఉంచడం. ఖాళీగా ఉంచితే రూల్స్ వర్తిస్తాయి.",
    "site.admin.hospital.bloodCentre.nat": "విడుదల చేసే ముందు ప్రతి డొనేషన్‌పై NAT అవసరం",
    "site.admin.hospital.bloodCentre.natNote": "Rules ప్రకారం అవసరం లేదు. మార్చి 2026లో NAT ను తప్పనిసరి చేయడానికి ప్రభుత్వం నిరాకరించిందని నివేదికలు చెబుతున్నాయి; అది ప్రాథమిక పాఠం నుండి ధృవీకరించబడలేదు.",
    "site.admin.hospital.bloodCentre.sampleDays": "ఇష్యూ చేసిన తర్వాత పైలట్ మరియు గ్రహీత శాంపిల్స్‌ను ఉంచాల్సిన రోజులు",
    "site.admin.hospital.bloodCentre.recordYears": "బ్లడ్ సెంటర్ రికార్డులను ఉంచాల్సిన సంవత్సరాలు",
    "site.admin.hospital.bloodCentre.shelfHeading": "తక్కువ షెల్ఫ్ లైవ్‌లు (గంటలు)",
    "site.admin.hospital.bloodCentre.shelfFor": "Rules గరిష్టంగా {limit} వరకు అనుమతిస్తాయి",
    "site.blood.shelfUnconfirmed": "చదివిన విధంగా Rulesలో ధృవీకరించబడలేదు, కాబట్టి ఇక్కడ అనుమతించబడదు: -40 C లేదా అంతకంటే తక్కువ ఉష్ణోగ్రత వద్ద ఉంచిన ఫ్రెష్ ఫ్రోజెన్ ప్లాస్మాకు ఎక్కువ షెల్ఫ్ లైఫ్ (ఒక సంవత్సరం ఉంచబడుతుంది), మరియు యాడిటివ్ సొల్యూషన్ లేని రెడ్ సెల్స్‌కు విడిగా షెల్ఫ్ లైఫ్ (అవి ఒకే యాంటికోయాగులెంట్‌లో ఉండే హోల్ బ్లడ్ కంటే ఎక్కువ కాలం ఉండవు).",
