    "site.admin.security.lrNotShown": "CERT-In నిబంధనలకు అనుగుణంగా ఉన్నట్లు చూపబడలేదు.",
    "site.gov.tab.retention": "రిటెన్షన్ మరియు లీగల్ హోల్డ్స్",
    "site.gov.law.title": "ఏ ప్రైవసీ చట్టం వర్తిస్తుంది",
    "site.gov.law.dpdpNow": "{date} నుండి ఈ హాస్పిటల్‌కు DPDP Act 2023 మరియు DPDP Rules 2025 వర్తిస్తాయి. SPDI Rules 2011 మరియు CERT-In బాధ్యతలు కూడా కొనసాగుతాయి.",
    "site.gov.law.spdiNow": "ప్రస్తుతం IT Act s.43A, SPDI Rules 2011 మరియు CERT-In Directions 2022 వర్తిస్తాయి. హాస్పిటల్ యొక్క DPDP Act బాధ్యతలు (నోటీస్, కన్సెంట్, సెక్యూరిటీ, బ్రీచ్, హక్కులు, పిల్లలు) {date} న ప్రారంభమవుతాయి.",
    "site.gov.law.published": "DPDP Rules ప్రచురించబడ్డాయి",
