    "site.gov.ret.title": "రికార్డులు ఎంత కాలం భద్రపరచబడతాయి",
    "site.gov.ret.intro2": "ఎదీ ఆటోమేటిక్‌గా డిలీట్ చేయబడదు. ప్రతీ క్లాస్ దేని వల్ల ఉంచబడుతుందో చూపిస్తుంది: ఒక చట్టం (దాని నిబంధనతో సహా) లేదా ఆసుపత్రి రిటెన్షన్ పాలసీ (ఇది చట్టబద్ధమైన అవసరం కాదు). కేసు ముగిసే వరకు లీగల్ హోల్డ్ ప్రతిదానినీ ఉంచుతుంది. చట్టం నిర్ణయించిన వ్యవధిలో డాక్యుమెంట్‌ను డిలీట్ చేయడం తిరస్కరించబడుతుంది; పాలసీ మాత్రమే నిర్ణయించిన వ్యవధిలో దానికి DPO లేదా మెడికల్ రికార్డ్స్ ఆఫీసర్ నిర్ధారణ అవసరం.",
    "site.gov.ret.find": "రిటెన్షన్‌ను చూపించు",
    "site.gov.ret.loading": "ఏమి ఉంచాలో నిర్ణయిస్తోంది...",
