    "site.gov.ret.decIntro": "ఈ రికార్డులు ఏ చట్టం ద్వారా ఉంచబడలేదు. ప్రతిదానికీ, ఉంచి ఉద్దేశ్యం లేదా అవసరాన్ని రాయండి లేదా డిలీట్ చేయండి. WardSynQ క్లినికల్ రికార్డును నేరుగా డిలీట్ చేయదు: మెడికల్ రికార్డ్స్ ఆఫీసర్ దానిని నాశనం చేస్తారు లేదా డి-ఐడెంటిఫై చేస్తారు, మరియు డెస్ట్రక్షన్ రికార్డ్ రిఫరెన్స్‌తో అభ్యర్థన పూర్తవుతుంది.",
